await shot("app-project-failed-dark", `${A}/projects/mbappboss`);
await shot("app-new-dark", `${A}/new`, { act: async (p) => { await p.getByRole("button", { name: /Welcome titles/ }).click(); } });
await shot("app-new-empty-dark", `${A}/new`, { full: false });
await shot("app-new-phone", `${A}/new`, { view: "phone", act: async (p) => { await p.getByRole("button", { name: /Lucky mob drops/ }).click(); } });
await shot("app-account-profile-dark", `${A}/account`);
await shot("app-account-connections-dark", `${A}/account?tab=connections`, { act: async (p) => { await p.locator("details summary").click(); } });
await shot("app-account-keys-dark", `${A}/account?tab=keys`, { act: async (p) => { await p.getByLabel("Name").fill("Release pipeline"); await p.getByRole("button", { name: "Create key" }).click(); await p.waitForSelector('[data-testid="new-key"]', { timeout: 30000 }); } });
await shot("app-account-keys-phone", `${A}/account?tab=keys`, { view: "phone" });
await shot("app-account-notifications-dark", `${A}/account?tab=notifications`, { act: async (p) => { await p.getByRole("button", { name: "Save preferences" }).click(); await p.waitForSelector("text=Saved.", { timeout: 20000 }); } });
await shot("app-account-billing-dark", `${A}/account?tab=billing`);
await shot("app-account-data-dark", `${A}/account?tab=data`, { act: async (p) => { await p.getByRole("button", { name: "Request export" }).click(); await p.waitForTimeout(1500); } });
await shot("app-account-light", `${A}/account?tab=keys`, { theme: "light" });
