/**
 * A refunded payment takes back the UNSPENT tokens it bought, in proportion to the amount
 * refunded (from that purchase's own lot only; tokens already spent stay spent).
 */
export async function handleRefundedCharge(ch: Stripe.Charge): Promise<number> {
  const pi = idOf(ch.payment_intent as string | { id: string } | null);
  if (!pi || !ch.amount || !ch.amount_refunded) return 0;
  const rows = await db.cyrusTokenLedger.findMany({ where: { kind: "purchase", meta: { path: ["paymentIntent"], equals: pi } } });
  let total = 0;
  for (const row of rows) {
    if (!row.lotId || row.delta <= 0) continue;
    const want = Math.round(row.delta * Math.min(1, ch.amount_refunded / ch.amount));
    const prior = await db.cyrusTokenLedger.findMany({ where: { kind: "revoke", sourceRef: row.id } });
    const already = prior.reduce((a, x) => a + ((x.meta as { requested?: number } | null)?.requested ?? 0), 0);
    if (want - already <= 0) continue;
    const r = await revokeTokens({ userId: row.userId, amount: want - already, lotIds: [row.lotId], sourceRef: row.id, idemKey: `refund:${ch.id}:${ch.amount_refunded}:${row.id}`, note: `Refund ${ch.id}`, meta: { charge: ch.id, refunded: ch.amount_refunded } });
    if (r.created) total += r.revoked;
  }
  return total;
}

