"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { MARK_ARM, MARK_SWEEP, MARK_VIEWBOX } from "@/components/cyrus/icons/cyrusMark";
import { Logo } from "./Logo";

/** The Cyrus "Y" mark in one ink (currentColor): same paths as the brand mark, no gradients. */
export function CyrusMarkSolid({ height = 14, className = "" }: { height?: number; className?: string }) {
  return (
    <svg viewBox={MARK_VIEWBOX} height={height} width={(height * 940) / 520} aria-hidden focusable="false" className={className}>
      <path d={MARK_SWEEP} fill="currentColor" />
      <path d={MARK_ARM} fill="currentColor" />
    </svg>
  );
}

/* Light mode = data-theme="light" on <html>. Class names stay LITERAL (Tailwind only generates classes it can read in
   the source, so no template-built variants). The header stays a dark island, so the black pill keeps a hairline.
   Outside the island the portal swaps the white/black tokens in light mode, so the back strip uses hex colours. */

/**
 * Cyrus' entry in the Nxeon top bar: a different product, so it is a plain inverse pill (white with the black mark;
 * black with the white mark in light mode). Opens Cyrus full screen (components/nx/Shell.tsx drops the portal chrome
 * on /dashboard/cyrus). No token balance here: Cyrus shows its own inside the studio.
 */
export function CyrusTopEntry({ beta }: { beta: boolean }) {
  return (
    <Link
      href="/dashboard/cyrus"
      aria-label="Open Cyrus, the AI mod studio"
      title="Cyrus: describe a mod, get a working Minecraft plugin"
      data-cyrus-entry
      className={`inline-flex h-9 flex-none items-center gap-2 rounded-full bg-white px-3 text-[13px] font-bold text-black shadow-[0_1px_0_rgba(255,255,255,.4)_inset,0_6px_18px_-10px_rgba(0,0,0,.9)] transition hover:-translate-y-px hover:bg-white/90 sm:px-3.5 [html[data-theme=light]_&]:bg-black [html[data-theme=light]_&]:text-white [html[data-theme=light]_&]:ring-1 [html[data-theme=light]_&]:ring-white/25 [html[data-theme=light]_&]:hover:bg-black/85`}
    >
      <CyrusMarkSolid height={12} />
      <span className="hidden sm:inline">Cyrus</span>
      {beta && <span className={`hidden rounded-full bg-black/10 px-1.5 py-px text-[9px] font-extrabold tracking-wider md:inline [html[data-theme=light]_&]:bg-white/20`}>BETA</span>}
    </Link>
  );
}

/**
 * The only Nxeon chrome left while Cyrus is open full screen: a slim strip with one way back to the page the user
 * came from in the portal (falls back to /dashboard).
 */
export function CyrusBackBar({ href }: { href: string }) {
  return (
    <div
      data-cyrus-backbar
      className={`relative z-30 flex h-9 flex-none items-center border-b border-white/10 bg-[#05060a] px-2 sm:px-3 [html[data-theme=light]_&]:border-[rgba(0,0,0,.1)] [html[data-theme=light]_&]:bg-[#f3f4f7]`}
    >
      <Link
        href={href}
        className={`inline-flex h-7 items-center gap-1.5 rounded-full border border-white/15 bg-white/[.04] pl-1.5 pr-3 text-[12px] font-semibold text-white/80 transition hover:border-white/30 hover:text-white [html[data-theme=light]_&]:border-[rgba(0,0,0,.16)] [html[data-theme=light]_&]:bg-[#ffffff] [html[data-theme=light]_&]:text-[#2a2d38] [html[data-theme=light]_&]:hover:text-[#000000]`}
