// r49 QA: real-browser journeys across nxeon.cloud, cyrus.my and admin.cyrus.my (fake hostnames mapped to 127.0.0.1 by
// Chromium's host resolver) against ONE `devhost dev` on node-2 with the Cyrus flags ON in that throwaway env only.
// Nothing here talks to Stripe/Meta/Google/email: card money is covered by test/cyrus-qa-journeys-db.test.ts (fake
// Stripe client), this script drives what a person clicks. Not part of the app.
//   devhost run -- node test/e2e/cyrus-qa-journeys.mjs   env: PORT, TOKENS (studio-fixtures json), ADMIN (admin token),
//   SEED (e2e-seed json), OUT (shots dir), REPORT (json path)
// Writes <OUT>/qa-*.png (every failure gets qa-fail-<id>.png) and a JSON list of {id, title, ok, detail}.
import { createRequire } from "node:module";
import { execFileSync } from "node:child_process";
import { readFileSync, mkdirSync, writeFileSync } from "node:fs";
const require = createRequire(import.meta.url);
const { chromium } = require("playwright");

const P = process.env.PORT ?? "3000";
const N = `http://nxeon.cloud:${P}`, C = `http://cyrus.my:${P}`, A = `http://admin.cyrus.my:${P}`;
const OUT = process.env.OUT ?? ".shots/qa";
const tok = JSON.parse(readFileSync(process.env.TOKENS ?? ".shots/tokens.json", "utf8"));
const seed = JSON.parse(readFileSync(process.env.SEED ?? ".shots/seed.json", "utf8"));
const ADMIN = process.env.ADMIN ?? "";
mkdirSync(OUT, { recursive: true });
const browser = await chromium.launch({ args: ["--host-resolver-rules=MAP nxeon.cloud 127.0.0.1, MAP cyrus.my 127.0.0.1, MAP admin.cyrus.my 127.0.0.1"] });
const results = [];
const seedCmd = (...a) => execFileSync("npx", ["tsx", "tools/cyrus-bridge/e2e-seed.ts", ...a], { encoding: "utf8" }).trim().split("\n").pop();

async function ctxFor({ theme = "dark", phone = false, nxeon, cyrus } = {}) {
  const ctx = await browser.newContext({ viewport: phone ? { width: 390, height: 844 } : { width: 1440, height: 900 }, isMobile: phone, hasTouch: phone, deviceScaleFactor: phone ? 2 : 1, colorScheme: theme });
  const ck = [{ name: "nxeon_cookie_consent", value: "all", url: N }];
  if (nxeon) ck.push({ name: tok.cookie ?? "nxeon_session", value: nxeon, url: N });
  if (cyrus) ck.push({ name: "cyrus_session", value: cyrus, url: C });
  await ctx.addCookies(ck);
  await ctx.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); localStorage.setItem("cyrus-app-tour-v1", "done"); } catch {} if (t === "light") document.addEventListener("DOMContentLoaded", () => document.documentElement.setAttribute("data-theme", "light")); }, theme);
  return ctx;
}
async function step(id, title, ctx, fn) {
  const page = ctx.pages()[0] ?? (await ctx.newPage());
  const errs = [];
  const onErr = (e) => errs.push(String(e).slice(0, 200));
  page.on("pageerror", onErr);
  let ok = false, detail = "";
  try { detail = (await fn(page)) ?? ""; ok = true; } catch (e) { detail = String(e?.message ?? e).split("\n")[0].slice(0, 300); }
  page.off("pageerror", onErr);
  if (errs.length) detail += ` | pageerror: ${errs.join(" ; ").slice(0, 200)}`;
