  try { detail = (await fn(page)) ?? ""; ok = true; } catch (e) { detail = String(e?.message ?? e).split("\n")[0].slice(0, 300); }
  page.off("pageerror", onErr);
  if (errs.length) detail += ` | pageerror: ${errs.join(" ; ").slice(0, 200)}`;
  if (!ok) await page.screenshot({ path: `${OUT}/qa-fail-${id}.png` }).catch(() => {});
  results.push({ id, title, ok, detail });
  console.log(`${ok ? "PASS" : "FAIL"} ${id} ${title}${detail ? " :: " + detail : ""}`);
  return ok;
}
