  const ctx = await ctxFor(); const email = `e2e-bridge-qa-${Date.now().toString(36)}@example.test`;
  await step("signup-start", "cyrus.my sign-in -> 'Create a Cyrus account' -> Nxeon consent (create)", ctx, async (p) => {
    await go(p, `${C}/sign-in`); await shot(p, "signin-cyrus-dark");
    await p.getByRole("link", { name: /Create a Cyrus account|Create account with Nxeon/ }).first().click();
    await p.waitForURL(/nxeon\.cloud.*\/sso\/cyrus\/consent/, { timeout: 120000 });
    must(await p.getByText(/is a Nxeon account/).count(), "consent does not explain one account");
    await shot(p, "signup-consent");
  });
  await step("signup-agree", "tick agree -> Nxeon /register (coming back to authorize)", ctx, async (p) => {
    await p.locator('input[name="agree"][type="checkbox"]').check();
    await p.getByRole("button", { name: /Agree and create account/ }).click();
    await p.waitForURL(/nxeon\.cloud.*\/register\?next=/, { timeout: 120000 });
  });
  await step("signup-register", "real /register form creates the Nxeon account; unverified -> verify step", ctx, async (p) => {
    await p.locator('input[name="name"]').fill("QA Journey");
    await p.locator('input[name="email"]').fill(email);
    await p.locator('input[name="password"]').first().fill("QaJourney-2026-long!");
    const terms = p.locator('input[type="checkbox"][name="terms"], input[type="checkbox"][name="agree"]'); if (await terms.count()) await terms.first().check();
    await p.locator('form button[type="submit"]').first().click();
    await p.waitForURL(/consent\?.*verify=1|\/dashboard|\/verify/, { timeout: 120000 });
    return p.url().replace(N, "");
  });
  await step("signup-verified", "after verification the same handshake lands signed in on cyrus.my/studio", ctx, async (p) => {
    seedCmd("verify-email", email);
    const q = new URL(p.url()).searchParams.get("q");
    await go(p, q ? `${N}/sso/cyrus/authorize?${q}` : `${C}/auth/nxeon/start?next=/studio`);
    if (/\/sso\/cyrus\/consent/.test(p.url())) { const b = p.getByRole("button", { name: /Continue to Cyrus|Agree/ }); await b.first().click(); }
    await p.waitForURL(/cyrus\.my.*\/studio/, { timeout: 180000 });
    must(host(p) === "cyrus.my", "not on cyrus.my"); await shot(p, "signup-landed-studio");
    const st = JSON.parse(seedCmd("state", JSON.parse(seedCmd("verify-email", email)).userId));
    must(st.sessions.length >= 1, "no Nxeon session row for the new account");
  });
  await ctx.close();
}

// ---- J2 Sign in with Nxeon (signed in on Nxeon already; first time = consent) ----
let cyrusCookie = null;
{
  const ctx = await ctxFor({ nxeon: seed.nxeonSession });
  await step("sso-nxeon", "cyrus.my 'Sign in with Nxeon' -> consent -> back on cyrus.my/studio with a Cyrus session", ctx, async (p) => {
    await go(p, `${C}/sign-in`);
    await p.getByRole("link", { name: "Sign in with Nxeon" }).or(p.getByRole("button", { name: "Sign in with Nxeon" })).first().click();
    await p.waitForURL(/consent|cyrus\.my.*\/studio/, { timeout: 120000 });
    if (/consent/.test(p.url())) { await shot(p, "sso-consent"); await p.getByRole("button", { name: /Continue to Cyrus/ }).click(); }
    await p.waitForURL(/cyrus\.my.*\/studio/, { timeout: 180000 });
    const ck = (await ctx.cookies(C)).find((c) => c.name === "cyrus_session"); must(ck, "no cyrus_session cookie");
    must(ck.httpOnly, "cyrus_session not httpOnly"); cyrusCookie = ck.value;
    must(await p.getByText("A Nxeon product").count(), "Cyrus host chrome missing"); await shot(p, "sso-studio-cyrus");
  });
  // ---- J3 Sign in with Cyrus on Nxeon (only signed in on cyrus.my) ----
  await step("sso-cyrus", "nxeon.cloud /login 'Sign in with Cyrus' -> Nxeon dashboard", ctx, async (p) => {
    await ctx.clearCookies({ domain: "nxeon.cloud" }).catch(async () => { const keep = (await ctx.cookies()).filter((c) => c.domain !== "nxeon.cloud"); await ctx.clearCookies(); await ctx.addCookies(keep); });
    await go(p, `${N}/login`); await shot(p, "login-nxeon-sign-in-with-cyrus");
    await p.getByRole("link", { name: /Sign in with Cyrus/ }).first().click();
    await p.waitForURL(/nxeon\.cloud.*\/dashboard/, { timeout: 180000 });
    must(!/\/login/.test(p.url()), "ended on login");
  });
  // ---- J4 logout propagation ----
  await step("logout", "Sign out on cyrus.my ends the Nxeon session too", ctx, async (p) => {
    await go(p, `${C}/studio`);
    await p.getByRole("button", { name: "Sign out" }).or(p.getByRole("link", { name: "Sign out" })).first().click();
    await p.waitForURL(/cyrus\.my.*\/sign-in\?signed_out=1/, { timeout: 120000 });
    await go(p, `${N}/dashboard`); must(/\/login/.test(p.url()), `nxeon.cloud still signed in: ${p.url()}`);
    await go(p, `${C}/studio`); must(/sign-in/.test(p.url()), "cyrus.my still signed in");
  });
  await ctx.close();
}

// ---- J5 one wallet, either site: top-up with an idempotency key on cyrus.my and on nxeon.cloud; credited once ----
{
  const s2 = JSON.parse(seedCmd("seed"));
  const ctx = await ctxFor({ nxeon: s2.nxeonSession });
  await step("wallet-both-hosts", "wallet top-up on nxeon.cloud then cyrus.my (same key twice each) -> 2 credits, never 4", ctx, async (p) => {
    await go(p, `${N}/dashboard`);
    const k1 = `qa-n-${Date.now()}-abcdefghij`, k2 = `qa-c-${Date.now()}-abcdefghij`;
    for (const k of [k1, k1]) { const r = await p.request.post(`${N}/api/cyrus/tokens/wallet`, { headers: { "Idempotency-Key": k, "content-type": "application/json", Origin: N }, data: { cents: 500 } }); must(r.status() === 200, `nxeon wallet ${r.status()} ${await r.text()}`); }
    // sign in on cyrus.my through the real handshake, then pay there
    await go(p, `${C}/auth/nxeon/start?next=/studio`); if (/consent/.test(p.url())) await p.getByRole("button", { name: /Continue to Cyrus/ }).click();
    await p.waitForURL(/cyrus\.my.*\/studio/, { timeout: 180000 });
    for (const k of [k2, k2]) { const r = await p.request.post(`${C}/api/cyrus/tokens/wallet`, { headers: { "Idempotency-Key": k, "content-type": "application/json", Origin: C }, data: { cents: 500 } }); must(r.status() === 200, `cyrus wallet ${r.status()} ${await r.text()}`); }
    const st = JSON.parse(seedCmd("state", s2.userId));
    must(st.balanceCents === 1000, `wallet ${st.balanceCents} (want 2000-1000)`); must(st.tokens === 1200, `tokens ${st.tokens} (want 1200)`);
    const tn = await (await p.request.get(`${N}/api/cyrus/tokens`)).json().catch(() => ({})); const tc = await (await p.request.get(`${C}/api/cyrus/tokens`)).json().catch(() => ({}));
    must(tn.balance === tc.balance, `balances differ ${tn.balance} vs ${tc.balance}`);
    return `wallet ${st.balanceCents}c, tokens ${st.tokens}, both hosts ${tc.balance}`;
  });
  await step("wallet-ui", "tokens screen shows 'Pay from wallet' (customer app billing tab)", ctx, async (p) => {
    await go(p, `${C}/account?tab=billing`);
    await p.getByRole("button", { name: /Top up/ }).first().click(); await p.waitForSelector("[data-wallet-pay]", { timeout: 60000 }); await shot(p, "wallet-topup-cyrus");
  });
  await ctx.close();
}

// ---- J6 full-screen Cyrus, Back to Nxeon, top-bar button states (dark + light) ----
for (const theme of ["dark", "light"]) {
  const ctx = await ctxFor({ theme, nxeon: tok.all.token });
  await step(`fullscreen-${theme}`, `${theme}: Nxeon top-bar Cyrus pill (inverse colours) -> full-screen Cyrus -> Back to Nxeon`, ctx, async (p) => {
    await go(p, `${N}/dashboard`); const pill = p.locator("[data-cyrus-entry]").first(); await pill.waitFor({ timeout: 120000 });
    const bg = await pill.evaluate((e) => getComputedStyle(e).backgroundColor);
    must(theme === "dark" ? /255, 255, 255/.test(bg) : /\(0, 0, 0/.test(bg), `pill background ${bg} in ${theme}`);
    must(!(await p.locator("[data-cyrus-tokens-chip], [data-cyrus-credit]").count()), "Cyrus credit widget still in the Nxeon bar");
    await shot(p, `topbar-pill-${theme}`);
    await pill.click(); await p.waitForURL(/\/dashboard\/cyrus/, { timeout: 180000 });
    await p.locator("[data-cyrus-backbar]").waitFor({ timeout: 60000 }); must(!(await p.locator("[data-cyrus-entry]").count()), "portal top bar still rendered in Cyrus");
    await shot(p, `fullscreen-${theme}`);
    await p.getByRole("link", { name: /Back to Nxeon/ }).click(); await p.waitForURL((u) => !u.pathname.startsWith("/dashboard/cyrus"), { timeout: 120000 });
    return `pill ${bg}`;
  });
  await ctx.close();
}

// ---- J7 customer app on both hosts + new-mod flow (cost first) + live meter ----
{
  const ctx = await ctxFor({ nxeon: tok.all.token });
  await step("app-pages-nxeon", "customer app pages render on nxeon.cloud (home, projects, project, account)", ctx, async (p) => {
    for (const [u, n] of [["/dashboard/cyrus/app", "app-home"], ["/dashboard/cyrus/app/projects", "app-projects"], ["/dashboard/cyrus/app/projects/mbappbounty", "app-project"], ["/dashboard/cyrus/app/account", "app-account"]]) {
      const r = await go(p, N + u); must(r && r.status() === 200, `${u} -> ${r?.status()}`); await p.waitForSelector(".cx-page", { timeout: 120000 }); await shot(p, n);
    }
  });
  await step("newmod-cost-first", "new-mod flow shows the token cost before anything is spent", ctx, async (p) => {
    await go(p, `${N}/dashboard/cyrus/app/new`); await p.waitForSelector(".cx-page", { timeout: 120000 });
    const tpl = p.getByRole("button", { name: /Welcome titles|Lucky mob drops/ }).first(); if (await tpl.count()) await tpl.click();
    const cost = p.getByText(/tokens/i).first(); await cost.waitFor({ timeout: 30000 }); await shot(p, "newmod-cost");
    return (await cost.innerText()).slice(0, 80);
  });
  await step("live-meter", "running build shows the live token meter (estimated so far vs held)", ctx, async (p) => {
    await go(p, `${N}/dashboard/cyrus/mbappbounty3`); const m = p.locator("[data-token-meter], .cy-meter, [data-live-meter]").first();
    await m.waitFor({ timeout: 120000 }); await shot(p, "live-meter"); return (await m.innerText()).replace(/\s+/g, " ").slice(0, 100);
  });
  await step("api-key", "create a personal API key in the account tab, call /api/cyrus/v1 with it, other scopes refused", ctx, async (p) => {
    await go(p, `${N}/dashboard/cyrus/app/account?tab=keys`); await p.getByLabel("Name").fill("QA journey key");
    await p.getByRole("button", { name: "Create key" }).click(); const k = (await p.locator('[data-testid="new-key"]').innerText({ timeout: 60000 })).trim();
    await shot(p, "api-key-created");
    const r = await p.request.get(`${N}/api/cyrus/v1/projects`, { headers: { Authorization: `Bearer ${k}`, Cookie: "" } }); must(r.status() === 200, `projects ${r.status()} ${(await r.text()).slice(0, 120)}`);
    const bad = await p.request.get(`${N}/api/cyrus/v1/projects`, { headers: { Authorization: `Bearer ${k.slice(0, -2)}xx`, Cookie: "" } }); must(bad.status() === 401, `tampered key -> ${bad.status()}`);
    const w = await p.request.post(`${N}/api/cyrus/v1/builds`, { headers: { Authorization: `Bearer ${k}`, "content-type": "application/json", Cookie: "" }, data: { prompt: "x" } }); must([401, 403].includes(w.status()), `write with read key -> ${w.status()}`);
    return `read 200, tampered 401, write ${w.status()}`;
  });
  await step("data-export", "request a data export; another account cannot fetch it", ctx, async (p) => {
    await go(p, `${N}/dashboard/cyrus/app/account?tab=data`); await p.getByRole("button", { name: "Request export" }).click(); await p.waitForTimeout(2000); await shot(p, "data-export");
    const o = await browser.newContext(); const op = await o.newPage(); await o.addCookies([{ name: tok.cookie ?? "nxeon_session", value: tok.outsider?.token ?? seed.nxeonSession, url: N }]);
    const r = await op.request.get(`${N}/api/cyrus/data-export/does-not-belong-to-you`); await o.close(); must([403, 404].includes(r.status()), `foreign export -> ${r.status()}`);
  });
  await ctx.close();
}
// cyrus.my side of the app with a real Cyrus session
if (cyrusCookie) {
  const s3 = JSON.parse(seedCmd("seed")); const ctx = await ctxFor({ nxeon: s3.nxeonSession });
  await step("app-cyrus-host", "customer app on cyrus.my: /home and /projects (public paths), portal pages hand off to Nxeon", ctx, async (p) => {
    await go(p, `${C}/auth/nxeon/start?next=/home`); if (/consent/.test(p.url())) await p.getByRole("button", { name: /Continue to Cyrus/ }).click();
    await p.waitForURL(/cyrus\.my.*\/(home|studio)/, { timeout: 180000 }); await go(p, `${C}/home`); await shot(p, "app-home-cyrus");
    await go(p, `${C}/projects`); must(host(p) === "cyrus.my", "left cyrus.my");
    const r = await go(p, `${C}/dashboard/billing`); must(host(p) === "nxeon.cloud", `billing not handed to Nxeon: ${p.url()} ${r?.status()}`);
  });
  await ctx.close();
}

// ---- J8 admin: moderation hold, kill switch, view-as read-only, reconcile; admin.cyrus.my not an admin surface ----
if (ADMIN) {
  const ctx = await ctxFor({ nxeon: ADMIN });
  await step("admin-holds", "library hold queue renders with Approve/Reject (moderation)", ctx, async (p) => { const r = await go(p, `${N}/admin/cyrus/library/holds`); must(r.status() === 200, `holds ${r.status()}`); await shot(p, "admin-holds"); });
  await step("admin-kill", "kill switch: Stop builds -> a new build is refused -> Resume (confirm) restores", ctx, async (p) => {
    await go(p, `${N}/admin/cyrus/flags`); const form = p.locator('form:has(input[name="kill"][value="cyrus_builds_paused"]), form:has(input[name="id"][value="cyrus_builds_paused"])').first();
    must(await form.count(), "no build-pause form"); await form.getByRole("button", { name: "Stop" }).click(); await p.waitForLoadState("load"); await shot(p, "admin-kill-stopped");
    const u = await browser.newContext(); await u.addCookies([{ name: tok.cookie ?? "nxeon_session", value: tok.all.token, url: N }]); const up = await u.newPage();
    const r = await up.request.post(`${N}/api/mod-builder/builds`, { headers: { "content-type": "application/json", Origin: N }, data: { prompt: "A /hello command that greets the player", mcVersion: "1.21.11" } });
    const body = await r.text(); await u.close(); must(r.status() >= 400 && /pause/i.test(body), `build not refused while paused: ${r.status()} ${body.slice(0, 120)}`);
    await go(p, `${N}/admin/cyrus/flags`); const f2 = p.locator('form:has(input[name="kill"][value="cyrus_builds_paused"]), form:has(input[name="id"][value="cyrus_builds_paused"])').first();
    const c = f2.locator('input[name="confirm"]'); if (await c.count()) await c.check(); await f2.getByRole("button", { name: "Resume" }).click(); await p.waitForLoadState("load");
    return `paused build -> ${r.status()}`;
  });
  await step("admin-viewas", "view-as: audited read-only page; customer actions are not reachable from it", ctx, async (p) => {
    await go(p, `${N}/admin/cyrus/users?u=usr_cfix_a`); await p.locator('input[name="reason"]').first().fill("QA-49 journey");
    await p.getByRole("button", { name: /View their Cyrus \(read-only\)/ }).click(); await p.waitForURL(/\/admin\/cyrus\/view\//, { timeout: 120000 });
    must(!(await p.locator("form button").filter({ hasText: /Install|Delete|Create|Rebuild|Spend/ }).count()), "mutating buttons on view-as page"); await shot(p, "admin-viewas");
    const ck = (await ctx.cookies(N)).map((c) => c.name); must(!ck.some((n) => /imp/.test(n)), "view-as set an impersonation cookie");
  });
  await step("admin-reconcile", "reconciliation page: run reconcile now + dead webhook replay controls", ctx, async (p) => { const r = await go(p, `${N}/admin/cyrus/reconcile`); must(r.status() === 200, `reconcile ${r.status()}`); await p.getByRole("button", { name: "Run reconcile now" }).click(); await p.waitForLoadState("load"); await shot(p, "admin-reconcile"); });
  await step("admin-host", "admin.cyrus.my: no Cyrus admin is served there yet (owner: nginx decides); cyrus.my/admin 404", ctx, async (p) => {
    const r1 = await p.request.get(`${C}/admin`, { maxRedirects: 0 }); must(r1.status() === 404, `cyrus.my/admin ${r1.status()}`);
    const r2 = await p.request.get(`${A}/admin/cyrus`, { maxRedirects: 0 }); return `admin.cyrus.my/admin/cyrus -> ${r2.status()} (unknown host = Nxeon app; nginx must not route it)`;
  });
  await ctx.close();
}
// phone check of the two entry pages
{ const ctx = await ctxFor({ phone: true }); await step("phone-signin", "phone: cyrus.my sign-in has no horizontal overflow", ctx, async (p) => { await go(p, `${C}/sign-in`); const o = await p.evaluate(() => document.documentElement.scrollWidth - innerWidth); await shot(p, "signin-phone"); must(o <= 1, `overflow ${o}px`); }); await ctx.close(); }

await browser.close();
writeFileSync(process.env.REPORT ?? `${OUT}/qa-journeys.json`, JSON.stringify(results, null, 1));
const f = results.filter((r) => !r.ok).length; console.log(`RESULT ${results.length - f}/${results.length} passed`);

