import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";

/**
 * r41 DB checks: plan tokens roll over while active, the rollover cap, the lapse rules (freeze / grace / expire, back on
 * resubscribe), server-token scope + per-server cap, refund / early-delete reversal, and the Nxeon -> Cyrus server events
 * landing on the same keys as the direct calls. THROWAWAY Postgres only (no Stripe network: a fake client).
 *
 * Opt-in, fail closed: CYRUS_R41_TEST_DATABASE_URL must equal DATABASE_URL, be localhost and name a throwaway database
 * (devhost's wt_<name> or *_cyrustokens).
 *   devhost run -- bash -c 'CYRUS_R41_TEST_DATABASE_URL=$DATABASE_URL npx tsx --test test/cyrus-tokens-r41-db.test.ts'
 */
const url = process.env.CYRUS_R41_TEST_DATABASE_URL;
const safe = !!url && url === process.env.DATABASE_URL && /^postgres(ql)?:\/\/[^@]*@(localhost|127\.0\.0\.1)(:\d+)?\/(wt_[a-z0-9_]+|[a-z_]*_cyrustokens)(\?[A-Za-z0-9_=&]*)?$/.test(url);
const skip = safe ? false : "set CYRUS_R41_TEST_DATABASE_URL (= DATABASE_URL, a throwaway wt_* db) to run";

type Db = typeof import("../lib/db.ts")["db"];
let db: Db;
let L: typeof import("../lib/cyrus/tokens/ledger.ts");
let G: typeof import("../lib/cyrus/tokens/grants.ts");
let S: typeof import("../lib/cyrus/tokens/billing.ts");
let C: typeof import("../lib/cyrus/tokens/config.ts");
let H: typeof import("../lib/cyrus/bridge/platform-event-handlers.ts");
const DAY = 86_400_000;
const uniq = () => `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
const users: string[] = [];

async function mkUser() {
  const u = await db.user.create({ data: { email: `cyt41-${uniq()}@example.test`, passwordHash: "x", name: "Cyrus r41 Test" } });
  users.push(u.id);
  return u;
}
async function setting(key: string, value: string | null) {
  if (value === null) await db.setting.deleteMany({ where: { key } });
  else await db.setting.upsert({ where: { key }, update: { value }, create: { key, value } });
  C.clearTokenConfigCache();
}
const sum = (userId: string) => L.tokenSummary(userId);

type Inv = Record<string, unknown>;
function fakeStripe(state: { subs: Record<string, Record<string, unknown>>; invoices: Inv[] }) {
  const price = (tier: string) => ({ id: `price_${tier}`, lookup_key: `cyrus_plan_${tier}_v1`, unit_amount: { katara: 499, saka: 1999, all: 4999 }[tier], currency: "usd", livemode: false, metadata: {} });
  return {
    prices: { list: async () => ({ data: ["katara", "saka", "all"].map(price) }), retrieve: async (id: string) => price(id.replace("price_", "")) },
    subscriptions: { retrieve: async (id: string) => state.subs[id], update: async () => ({}) },
test/cyrus-tokens-ledger-db.test.ts:57:  S.setCyrusStripeForTests(null);
test/cyrus-tokens-ledger-db.test.ts:246:function fakeStripe(state: { subs: Record<string, Record<string, unknown>>; invoices: Inv[]; sessions: Record<string, Record<string, unknown>> }) {
test/cyrus-tokens-ledger-db.test.ts:277:    S.setCyrusStripeForTests(fakeStripe(state) as never);
test/cyrus-tokens-ledger-db.test.ts:305:    S.setCyrusStripeForTests(fakeStripe(state) as never);
test/cyrus-tokens-ledger-db.test.ts:327:    S.setCyrusStripeForTests(fakeStripe(state) as never);

// ---------------------------------------------------------------------------
// Stripe webhooks with a fake client (replays, stacking, upgrade, refund)
// ---------------------------------------------------------------------------

type Inv = Record<string, unknown>;
function fakeStripe(state: { subs: Record<string, Record<string, unknown>>; invoices: Inv[]; sessions: Record<string, Record<string, unknown>> }) {
  const price = (tier: string) => ({ id: `price_${tier}`, lookup_key: `cyrus_plan_${tier}_v1`, unit_amount: { katara: 499, saka: 1999, all: 4999 }[tier], currency: "usd", livemode: false, metadata: {} });
  return {
    prices: {
      list: async () => ({ data: ["katara", "saka", "all"].map(price) }),
      retrieve: async (id: string) => price(id.replace("price_", "")),
    },
    subscriptions: { retrieve: async (id: string) => state.subs[id], update: async () => ({}) },
    invoices: { list: async (q: { subscription: string }) => ({ data: state.invoices.filter((i) => (i.parent as { subscription_details: { subscription: string } }).subscription_details.subscription === q.subscription).slice().reverse() }) },
    invoicePayments: { list: async () => ({ data: [] }) },
    checkout: { sessions: { retrieve: async (id: string) => state.sessions[id], create: async () => ({ client_secret: "cs_secret" }) } },
    customers: { create: async () => ({ id: `cus_${uniq()}` }) },
  };
}
const sub = (id: string, userId: string, tier: string, status = "active", end = Date.now() + 30 * DAY) => ({
  id, status, customer: "cus_x", livemode: false, cancel_at_period_end: false, ended_at: null as number | null,
  metadata: { cyrusUserId: userId, cyrusTier: tier },
  items: { data: [{ id: "si_1", price: { id: `price_${tier}`, lookup_key: `cyrus_plan_${tier}_v1`, metadata: {} }, current_period_start: Math.floor((end - 30 * DAY) / 1000), current_period_end: Math.floor(end / 1000) }] },
});
const inv = (id: string, subId: string, userId: string, tier: string, reason: string, paid: number, pi: string) => ({
  id, status: "paid", billing_reason: reason, amount_paid: paid, livemode: false,
  parent: { subscription_details: { subscription: subId, metadata: { cyrusUserId: userId } } },
  payments: { data: [{ payment: { payment_intent: pi } }] },
  lines: { data: [{ amount: paid, period: { end: Math.floor((Date.now() + 30 * DAY) / 1000) }, pricing: { price_details: { price: `price_${tier}` } } }] },
});
