describe("r41 server tokens: scope, per-server cap, reversal, events", { skip }, () => {
  it("per-server lifetime cap applies across initial + renewals", async () => {
    await setting("cyrus_tok_grant_per_server_cap", "500");
    const u = await mkUser();
    const serverId = `srv_${uniq()}`;
    const a = await G.grantForGameServerPurchase({ userId: u.id, serverId, gameFamily: "minecraft", chargeCents: 3000, termMonths: 1 });
    assert.ok(a?.created && a.amount > 0 && a.amount <= 500);
    let total = a!.amount;
    for (let i = 0; i < 5; i++) total += (await G.grantForGameServerRenewal({ userId: u.id, serverId, gameFamily: "minecraft", netCents: 3000, months: 1, periodStart: new Date(Date.now() + i * 31 * DAY) }))?.amount ?? 0;
    assert.equal(total, 500);
    await setting("cyrus_tok_grant_per_server_cap", null);
  });
  it("scope: a non-Cyrus game earns nothing by default, and does with all_game_servers", async () => {
    const u = await mkUser();
    assert.equal(await G.grantForGameServerPurchase({ userId: u.id, serverId: `srv_${uniq()}`, gameFamily: "bedrock", chargeCents: 1000, termMonths: 1 }), null);
    await setting("cyrus_tok_grant_scope", "all_game_servers");
    assert.ok((await G.grantForGameServerPurchase({ userId: u.id, serverId: `srv_${uniq()}`, gameFamily: "bedrock", chargeCents: 1000, termMonths: 1 }))?.created);
    await setting("cyrus_tok_grant_scope", null);
  });
  it("refund takes back only that server's unspent tokens, once; early delete inside the window, never after", async () => {
    const u = await mkUser();
    const s1 = `srv_${uniq()}`, s2 = `srv_${uniq()}`;
    const g1 = await G.grantForGameServerPurchase({ userId: u.id, serverId: s1, gameFamily: "minecraft", chargeCents: 1000, termMonths: 1 });
    const g2 = await G.grantForGameServerPurchase({ userId: u.id, serverId: s2, gameFamily: "minecraft", chargeCents: 1000, termMonths: 1 });
    const before = (await sum(u.id)).balance;
    const r1 = await G.reverseServerGrants({ userId: u.id, serverId: s1, reason: "refund", ref: "re_1" });
    assert.equal(r1.revoked, g1!.amount);
    assert.equal((await G.reverseServerGrants({ userId: u.id, serverId: s1, reason: "refund", ref: "re_1" })).revoked, 0, "idempotent");
    assert.equal((await sum(u.id)).balance, before - g1!.amount);
    // deleted after the clawback window: kept
    assert.equal((await G.reverseServerGrants({ userId: u.id, serverId: s2, reason: "deleted", now: new Date(Date.now() + 15 * DAY) })).skipped, "outside clawback window");
    // deleted inside it: back
    assert.equal((await G.reverseServerGrants({ userId: u.id, serverId: s2, reason: "deleted" })).revoked, g2!.amount);
    // someone else's server id: nothing
    const other = await mkUser();
    assert.equal((await G.reverseServerGrants({ userId: other.id, serverId: s1, reason: "refund", ref: "x" })).skipped, "no grant");
  });
  it("Nxeon -> Cyrus events land on the same keys as the direct calls (never twice)", async () => {
    const u = await mkUser();
    const serverId = `srv_${uniq()}`;
    const h = H.platformEventHandlers();
    const e = (type: string, data: Record<string, unknown>) => ({ id: `evt_${uniq()}`, type, createdAt: new Date().toISOString(), subject: u.id, data });
    await G.grantForGameServerPurchase({ userId: u.id, serverId, gameFamily: "minecraft", chargeCents: 1000, termMonths: 1 });
    const b1 = (await sum(u.id)).balance;
    assert.deepEqual(await h["server.purchased"]!(e("server.purchased", { serverId, gameFamily: "minecraft", chargeCents: 1000, termMonths: 1 })), { granted: 0 });
    assert.equal((await sum(u.id)).balance, b1);
    const ps = new Date(Date.now() + 30 * DAY).toISOString();
    const r = await h["server.renewed"]!(e("server.renewed", { serverId, gameFamily: "minecraft", netCents: 1000, months: 1, periodStart: ps })) as { granted: number };
    assert.ok(r.granted > 0);
    assert.deepEqual(await h["server.renewed"]!(e("server.renewed", { serverId, gameFamily: "minecraft", netCents: 1000, months: 1, periodStart: ps })), { granted: 0 });
    // bad payloads do nothing
    assert.deepEqual(await h["server.purchased"]!(e("server.purchased", { serverId, chargeCents: "1000" })), { granted: 0 });
    const rf = await h["server.refunded"]!(e("server.refunded", { serverId, ref: "re_9", cents: 1000 })) as { revoked: number };
    assert.equal((await sum(u.id)).balance, 0, "all of this server's tokens were unspent, all came back");
  });
});

