import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";

/**
 * r49 QA money journey on ONE account, end to end through the real billing/ledger/grant code (THROWAWAY Postgres; Stripe
 * is a fake client, nothing leaves the box): a plan bought from cyrus.my and a token pack from nxeon.cloud (each
 * checkout returns to the host it started on), every webhook replayed + the return leg -> credited once; a Nxeon game
 * server deploy + renewal earn the placeholder free tokens; the plan renews and rolls over (no expiry while active);
 * spend through a build reservation; the pack refund takes back only its own unspent tokens, once; the early delete of
 * the server claws back its grant. At every step the ledger invariant holds (sum of deltas = sum of lot remaining).
 *   devhost run -- bash -c 'CYRUS_QA_TEST_DATABASE_URL=$DATABASE_URL npx tsx --test test/cyrus-qa-journeys-db.test.ts'
 */
const url = process.env.CYRUS_QA_TEST_DATABASE_URL;
const safe = !!url && url === process.env.DATABASE_URL && /^postgres(ql)?:\/\/[^@]*@(localhost|127\.0\.0\.1)(:\d+)?\/wt_[a-z0-9_]+(\?[A-Za-z0-9_=&]*)?$/.test(url);
const skip = safe ? false : "set CYRUS_QA_TEST_DATABASE_URL (= DATABASE_URL, a throwaway wt_* db) to run";

type Db = typeof import("../lib/db.ts")["db"];
let db: Db;
let L: typeof import("../lib/cyrus/tokens/ledger.ts");
let G: typeof import("../lib/cyrus/tokens/grants.ts");
let S: typeof import("../lib/cyrus/tokens/billing.ts");
let C: typeof import("../lib/cyrus/tokens/config.ts");
const DAY = 86_400_000;
const uniq = () => `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
const users: string[] = [];
const ev = (type: string, object: unknown) => ({ id: `evt_${uniq()}`, type, data: { object } }) as unknown as import("stripe").Stripe.Event;

type Rec = Record<string, unknown>;
function fakeStripe(state: { subs: Record<string, Rec>; invoices: Rec[]; sessions: Record<string, Rec>; created: Rec[] }) {
