      assert.equal(await code(me.read(SERVER, "/opt/mc/server.properties", undefined, rb)), "rollback_only");
      assert.equal(await code(me.inventory(SERVER, rb)), "rollback_only");
      assert.equal(await code(me.logTail(SERVER, undefined, rb)), "rollback_only");
      assert.equal(await code(me.restart(SERVER, rb)), "ok");
      assert.equal(await code(me.restart(SERVER, { ...rb, idemKey: "rb-restart-2" } as never)), "budget_exhausted", "one rollback restart per operation");
    } finally { f3.close(); }
  });
  it("M5: an unsigned request is refused before its body is read; a chunked body past the cap is 413", async () => {
    let pulled = 0;
    const big = new ReadableStream<Uint8Array>({ pull(c) { pulled++; if (pulled > 4000) c.close(); else c.enqueue(new Uint8Array(64 * 1024)); } });
