    assert.equal(r.status, 401);
    assert.ok(pulled < 5, `body pulled ${pulled} times before the signature check`);
    const P = "/api/platform/cyrus/v1/servers/" + SERVER + "/files/write";
    const h = signRequest({ keyId: fx.keys.keyId, secret: fx.keys.secret, method: "POST", pathWithQuery: P, body: "", nowMs: Date.now() });
    let n = 0;
    const big2 = new ReadableStream<Uint8Array>({ pull(c) { n++; if (n > 2000) c.close(); else c.enqueue(new Uint8Array(64 * 1024)); } });
    const r2 = await fx.api.handle(new Request("http://x" + P, { method: "POST", body: big2, headers: h, duplex: "half" } as RequestInit));
    assert.equal(r2.status, 413);
    assert.ok(n < 2000, "stopped reading at the cap");
  });
});
