describe("bring your own vanilla files (BYO)", () => {
  it("off = 404; on without the private reference = 503 (fail closed)", async () => {
    const a = apiFor({});
    assert.equal((await G.handleByoVerify(post("/verify", { files: [{ path: "x", sha256: "a".repeat(64) }] }), a.deps, a.g)).status, 404);
    const b = apiFor({ env: { CYRUS_BYO_GAME_ASSETS: "1" } });
    assert.equal((await G.handleByoVerify(post("/verify", { files: [{ path: "x", sha256: "a".repeat(64) }] }), b.deps, b.g)).status, 503);
    assert.equal((await G.handleByoImport(post("/import", { projectId: PID, key: "stick_x", dataBase64: STICK_PNG.toString("base64") }), b.deps, b.g)).status, 503);
  });
  it("verifies by hash, imports only an unchanged vanilla texture, keeps it game-derived (job retention), never contributes, ships delta-only", async () => {
    const a = apiFor({ env: { CYRUS_BYO_GAME_ASSETS: "1" }, refDir: refFixture() });
    const v = await (await G.handleByoVerify(post("/verify", { files: [{ path: "x/stick.png", sha256: sha(STICK_PNG) }, { path: "mine.png", sha256: "e".repeat(64) }] }), a.deps, a.g)).json() as { files: { ok: boolean; vanilla: string | null }[] };
    assert.deepEqual(v.files.map((f) => [f.ok, f.vanilla]), [[true, "26.1.2 assets/minecraft/textures/item/stick.png"], [false, null]]);
    const other = encodePng(raster(16, () => [9, 9, 9, 255]));
    assert.equal((await G.handleByoImport(post("/import", { projectId: PID, key: "stick_x", dataBase64: other.toString("base64") }), a.deps, a.g)).status, 422);
    const r = await G.handleByoImport(post("/import", { projectId: PID, key: "stick_x", dataBase64: STICK_PNG.toString("base64"), expectedHeadId: null }), a.deps, a.g);
    assert.equal(r.status, 200, await r.clone().text());
    const body = await r.json() as { pack: { leftOut?: { name: string }[] }; base: { expiresAt?: string; source: string } };
    assert.equal(body.base.source, "byo"); assert.ok(body.base.expiresAt);
    assert.deepEqual(body.pack.leftOut?.map((x) => x.name), ["stick_x"], "unchanged vanilla texture is not packed");
    const row = a.store.assets_.at(-1)!;
    const prov = row.provenance as Record<string, unknown>;
    assert.equal(row.origin, "imported"); assert.equal(prov.legalClass, "game-derived"); assert.equal(prov.retention, "job"); assert.equal(prov.libraryEligible, false);
    assert.equal(a.contributed.length, 0);
    // an edit: the client strips `base`; the server carries it from the base row and the changed texture ships
    const doc = { ...(prov.doc as TextureDoc) }; delete (doc as { base?: unknown }).base;
    doc.paint = { ...doc.paint!, colors: [...doc.paint!.colors, "#00ff00"], set: doc.paint!.set.map((x, i) => (i === 1 ? doc.paint!.colors.length : x)) };
    const s2 = await saveTexture(a.deps.service, { userId: "u1", projectId: PID, key: "stick_x", doc, baseAssetId: row.id, expectedHeadId: (await a.store.project(PID))!.headRevisionId });
    const row2 = a.store.assets_.at(-1)!;
    assert.equal(((row2.provenance as { doc: TextureDoc }).doc.base)?.source, "byo");
    assert.ok("sha1" in s2.pack && !s2.pack.leftOut);
    assert.equal(a.contributed.length, 0, "an edit of game-derived content is never contributed");
  });
});

