export const BAN_PREFIX = "ban: ";
export const isBan = (s: Suspension | null | undefined) => !!s && !s.until && s.scopes.includes("build") && s.scopes.includes("community") && s.reason.startsWith(BAN_PREFIX);

// ---------------------------------------------------------------------------
// GDPR: every Cyrus table that holds a person's data, and what an erasure does to it. Financial rows are RETAINED
// (anonymised later by the owner's retention rule: they back invoices and refunds); content is deleted; shared
// artefacts other people rely on (library contributions, forks) are anonymised, never broken.
// ---------------------------------------------------------------------------

export type GdprPolicy = "delete" | "anonymise" | "retain";
/** `id`: how the person appears in the column: the user id itself (default), or the library's opaque ids
 *  (contributor = HMAC "cyrus-contrib", libraryReporter = "u:" + HMAC viewer id), both keyed by CYRUS_LIBRARY_URL_SECRET. */
export type GdprTable = { model: string; field: string; policy: GdprPolicy; why: string; id?: "contributor" | "libraryReporter" };

export const CYRUS_GDPR_TABLES: GdprTable[] = [
  { model: "modBuild", field: "userId", policy: "anonymise", why: "Build records back token charges; the prompt and plugin name are cleared, the cost row stays." },
  { model: "cyrusProject", field: "userId", policy: "delete", why: "The person's projects (revisions and project assets go with them)." },
  { model: "cyrusModelDraft", field: "ownerRef", policy: "delete", why: "Model Studio autosaves." },
  { model: "cyrusTokenAccount", field: "userId", policy: "retain", why: "Balance record behind paid tokens (financial)." },
  { model: "cyrusTokenLot", field: "userId", policy: "retain", why: "Paid / granted token lots (financial)." },
  { model: "cyrusTokenLedger", field: "userId", policy: "retain", why: "Append-only money ledger (financial, refunds)." },
  { model: "cyrusTokenReservation", field: "userId", policy: "retain", why: "Per-build charges (financial)." },
  { model: "cyrusPlan", field: "userId", policy: "retain", why: "Subscription record (Stripe invoices refer to it)." },
  { model: "cyrusModPage", field: "userId", policy: "delete", why: "Published mod pages." },
  { model: "cyrusModPost", field: "userId", policy: "delete", why: "Community posts." },
  { model: "cyrusModReport", field: "userId", policy: "anonymise", why: "Reports the person filed (the moderation decision must stay explainable)." },
  { model: "cyrusFork", field: "userId", policy: "anonymise", why: "Fork links other creators' pages show." },
  { model: "cyrusModListing", field: "userId", policy: "delete", why: "Marketplace listings." },
  { model: "cyrusModMedia", field: "userId", policy: "delete", why: "Uploaded screenshots / media." },
  { model: "cyrusRemix", field: "userId", policy: "anonymise", why: "Remix credits on other creators' mods." },
  { model: "cyrusModStar", field: "userId", policy: "delete", why: "Stars." },
  { model: "cyrusModRating", field: "userId", policy: "delete", why: "Ratings." },
  { model: "cyrusLibraryItem", field: "userId", policy: "delete", why: "Saved library items." },
  { model: "cyrusCreator", field: "userId", policy: "delete", why: "Creator profile." },
  { model: "cyrusCollection", field: "userId", policy: "delete", why: "Collections." },
  { model: "cyrusCommunityReport", field: "userId", policy: "anonymise", why: "Community reports the person filed." },
  { model: "cyrusCreatorAlert", field: "userId", policy: "delete", why: "Creator alerts (compat watch)." },
  { model: "cyrusCatalogEntry", field: "contributorId", policy: "anonymise", why: "Automatic library contributions other projects use (licence kept, contributor id cleared).", id: "contributor" },
  { model: "cyrusLibraryReport", field: "reporter", policy: "anonymise", why: "Library reports the person filed.", id: "libraryReporter" },
];

      tables.cyrusPersonalApiKey = await cyrusDb.cyrusPersonalApiKey.findMany({ where: { userId }, select: { id: true, name: true, prefix: true, scopes: true, createdAt: true, lastUsedAt: true, expiresAt: true, revokedAt: true } });
      tables.cyrusDataRequest = await t.findMany({ where: { userId }, select: { id: true, kind: true, status: true, createdAt: true, completedAt: true } });
      const gs = await grantsProvider().state(userId).catch(() => ({ available: false as const, reason: "error" }));
      tables.serverGrants = gs.available ? gs.grants : [{ note: "server grants are kept by Nxeon and were not reachable from this job; see Nxeon > Connected apps" }];
      const counts = Object.fromEntries(Object.entries(tables).map(([k, v]) => [k, Array.isArray(v) ? v.length : 0]));
      const files = [
        { path: "README.txt", content: README(counts) },
        { path: "export.json", content: json({ schema: "cyrus-data-export/1", subject: g.subject, exportedAt: g.exportedAt, truncated: g.truncated, counts }) },
        ...Object.entries(tables).map(([k, v]) => ({ path: `tables/${k}.json`, content: json(v) })),
      ];
      return { files, counts };
    },
    async writeArchive(row, files) {
      const dir = exportDir(env);
      await mkdir(dir, { recursive: true, mode: 0o700 });
      const buf = Buffer.from(await zipFiles(files).arrayBuffer());
      const p = path.join(dir, `${row.id.replace(/[^A-Za-z0-9_-]/g, "").slice(0, 64)}-${randomBytes(8).toString("hex")}.zip`);
      await writeFile(p, buf, { mode: 0o600, flag: "wx" });
      return { path: p, bytes: buf.length, sha256: createHash("sha256").update(buf).digest("hex") };
    },
    async removeFile(p) { if (insideExportDir(p, env)) await unlink(p).catch(() => {}); },
    async archivesOf(userId) {
      const rows = await t.findMany({ where: { userId, kind: "export" }, select: { id: true, archivePath: true } });
      const ids = new Set(rows.map((r) => r.id));
      const known = rows.map((r) => r.archivePath).filter((x): x is string => !!x);
      // also sweep files whose row was already expired / retried (same id prefix)
      const onDisk = await readdir(exportDir(env)).catch(() => [] as string[]);
      const extra = onDisk.filter((f) => ids.has(f.replace(/-[a-f0-9]{16}\.zip$/, ""))).map((f) => path.join(exportDir(env), f));
      return [...new Set([...known, ...extra])].filter((p) => insideExportDir(p, env));
    },
    eraseEnabled: () => gdprEraseEnabled(env),
    erase: (userId) => gdprErase(userId),
    async eraseExtras(userId) {
      const out: Record<string, number> = {};
      out.cyrusPersonalApiKey = (await cyrusDb.cyrusPersonalApiKey.deleteMany({ where: { userId } })).count;
      out.cyrusNotificationPref = (await cyrusDb.cyrusNotificationPref.deleteMany({ where: { userId } })).count;
      out.cyrusNotification = (await cyrusDb.cyrusNotification.deleteMany({ where: { userId } })).count;
      // contributions not yet published leave the library; published ones stay (anonymised by gdprErase, takedown rule)
      const contributor = subjectValue({ id: "contributor" }, userId, env);
      out.unpublishedContributionsRemoved = contributor
        ? (await cyrusDb.cyrusCatalogEntry.updateMany({ where: { contributorId: contributor, status: { not: "published" } }, data: { status: "removed", statusReason: "contributor deleted their Cyrus data" } })).count
        : -1; // -1 = no library secret on this host: nothing could be matched
      const gp = grantsProvider();
      const gs = await gp.state(userId).catch(() => null);
      if (gs?.available) { let n = 0; for (const g of gs.grants) if (await gp.revoke(userId, g.serverId).catch(() => false)) n++; out.serverGrantsRevoked = n; }
      else out.serverGrantsRevoked = -1; // grants live at Nxeon and were not reachable: Nxeon's account flow covers them
      return out;
    },
    async audit(e) {
      await getHost().audit.append({ userId: e.userId, action: e.action, category: "cyrus", target: e.target, detail: JSON.stringify(e.detail).slice(0, 4000) });
    },
    log: (m) => console.error(m),
  };
}

