export function dataJobDeps(env: Record<string, string | undefined> = process.env): DataJobDeps {
  const t = cyrusDb.cyrusDataRequest;
  return {
    now: () => new Date(),
    async due(now) {
      const [exports, deletes, expired] = await Promise.all([
        t.findMany({ where: { kind: "export", status: "requested" }, orderBy: { createdAt: "asc" }, take: 10 }),
        t.findMany({ where: { kind: "delete", status: "requested", OR: [{ graceUntil: { lte: now } }, { graceUntil: null, createdAt: { lte: new Date(now.getTime() - DELETE_GRACE_DAYS * 86_400_000) } }] }, orderBy: { createdAt: "asc" }, take: 10 }),
        t.findMany({ where: { kind: "export", status: "ready", expiresAt: { lte: now } }, take: 50 }),
      ]);
      return { exports, deletes, expired } as { exports: JobRow[]; deletes: JobRow[]; expired: JobRow[] };
    },
    async claim(id, from, patch) { return (await t.updateMany({ where: { id, status: from }, data: patch as never })).count === 1; },
    async update(id, patch: JobPatch) { await t.update({ where: { id }, data: patch as never }); },
