// app, the studios, the Cyrus admin, the cyrus.my sign-in and the cyrus.my landing (static apps/cyrus-site), in dark and
// light. Runs ON node-2 against `devhost dev`. axe is NOT a dependency: AXE points at axe.min.js (npm pack axe-core).
//   devhost run -- node test/e2e/cyrus-qa-a11y.mjs   env: PORT, TOKENS, ADMIN, AXE, LANDING (static dir), OUT, ONLY
import { createRequire } from "node:module";
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { spawn } from "node:child_process";
const require = createRequire(import.meta.url);
const { chromium } = require("playwright");

const P = process.env.PORT ?? "3000";
const N = `http://nxeon.cloud:${P}`, C = `http://cyrus.my:${P}`;
const LP = String(Number(P) + 7); // landing static server
const OUT = process.env.OUT ?? ".shots/qa";
const tok = JSON.parse(readFileSync(process.env.TOKENS ?? ".shots/tokens.json", "utf8"));
const AXE = readFileSync(process.env.AXE ?? "test/e2e/.vendor/axe.min.js", "utf8");
const ADMIN = process.env.ADMIN ?? "";
mkdirSync(OUT, { recursive: true });
const landing = spawn("python3", ["-m", "http.server", LP, "--bind", "127.0.0.1", "--directory", process.env.LANDING ?? "apps/cyrus-site/src"], { stdio: "ignore" });
await new Promise((r) => setTimeout(r, 800));

const PAGES = [
  { id: "landing", url: `http://127.0.0.1:${LP}/`, who: null },
  { id: "signin-cyrus", url: `${C}/sign-in`, who: null },
  { id: "app-home", url: `${N}/dashboard/cyrus/app`, who: "all" },
  { id: "app-projects", url: `${N}/dashboard/cyrus/app/projects`, who: "all" },
  { id: "app-project", url: `${N}/dashboard/cyrus/app/projects/mbappbounty`, who: "all" },
  { id: "app-new", url: `${N}/dashboard/cyrus/app/new`, who: "all" },
  { id: "app-account", url: `${N}/dashboard/cyrus/app/account?tab=keys`, who: "all" },
  { id: "studio-home", url: `${N}/dashboard/cyrus`, who: "all" },
  { id: "studio-build", url: `${N}/dashboard/cyrus/mbappbounty2`, who: "all" },
  { id: "admin-home", url: `${N}/admin/cyrus`, who: "admin" },
  { id: "admin-flags", url: `${N}/admin/cyrus/flags`, who: "admin" },
  { id: "admin-holds", url: `${N}/admin/cyrus/library/holds`, who: "admin" },
];
const ONLY = process.env.ONLY ? process.env.ONLY.split(",") : null;
const browser = await chromium.launch({ args: ["--host-resolver-rules=MAP nxeon.cloud 127.0.0.1, MAP cyrus.my 127.0.0.1"] });
const results = [];
for (const pg of PAGES) {
  if (ONLY && !ONLY.includes(pg.id)) continue;
  if (pg.who === "admin" && !ADMIN) continue;
  for (const theme of ["dark", "light"]) {
    const ctx = await browser.newContext({ viewport: { width: 1280, height: 900 }, colorScheme: theme });
    const ck = [{ name: "nxeon_cookie_consent", value: "all", url: N }];
    if (pg.who) ck.push({ name: tok.cookie ?? "nxeon_session", value: pg.who === "admin" ? ADMIN : tok[pg.who].token, url: N });
    await ctx.addCookies(ck);
    await ctx.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); localStorage.setItem("cyrus-app-tour-v1", "done"); } catch {} if (t === "light") document.addEventListener("DOMContentLoaded", () => document.documentElement.setAttribute("data-theme", "light")); }, theme);
    const page = await ctx.newPage();
    const r = { page: pg.id, theme, status: 0, violations: [], focus: null, landmarks: null, motion: null, error: null };
    try {
      const res = await page.goto(pg.url, { waitUntil: "load", timeout: 240000 }); r.status = res?.status() ?? 0;
      await page.waitForTimeout(2500);
      await page.addScriptTag({ content: AXE });
      const ax = await page.evaluate(async () => (await window.axe.run(document, { runOnly: { type: "tag", values: ["wcag2a", "wcag2aa", "wcag21a", "wcag21aa"] }, resultTypes: ["violations"] })).violations.map((v) => ({ id: v.id, impact: v.impact, help: v.help, n: v.nodes.length, sample: v.nodes.slice(0, 3).map((x) => x.target.join(" ")).join(" | ").slice(0, 300) })));
      r.violations = ax;
      r.landmarks = await page.evaluate(() => ({ main: document.querySelectorAll("main,[role=main]").length, nav: document.querySelectorAll("nav,[role=navigation]").length, h1: document.querySelectorAll("h1").length, lang: document.documentElement.lang || null, skip: !!document.querySelector('a[href^="#"]:not([href="#"])') }));
      // keyboard: 20 Tabs; every focused element must show an indicator (outline or ring/box-shadow) and none may trap
      let noRing = [], seen = new Set();
      await page.locator("body").click({ position: { x: 2, y: 2 } }).catch(() => {});
      for (let i = 0; i < 20; i++) {
        await page.keyboard.press("Tab");
        const f = await page.evaluate(() => { const e = document.activeElement; if (!e || e === document.body) return null; const s = getComputedStyle(e); const ring = (s.outlineStyle !== "none" && parseFloat(s.outlineWidth) > 0) || (s.boxShadow && s.boxShadow !== "none"); return { tag: e.tagName.toLowerCase(), name: (e.getAttribute("aria-label") || e.textContent || "").trim().slice(0, 40), ring, key: e.tagName + (e.id || "") + (e.getAttribute("href") || "") + (e.textContent || "").slice(0, 20) }; });
        if (!f) continue; seen.add(f.key); if (!f.ring) noRing.push(`${f.tag}:${f.name}`);
      }
      r.focus = { reached: seen.size, noVisibleIndicator: [...new Set(noRing)].slice(0, 8), noRingCount: new Set(noRing).size };
    } catch (e) { r.error = String(e).slice(0, 200); }
    await ctx.close();
    // reduced motion: infinite animations still running with prefers-reduced-motion: reduce (dark only)
    if (theme === "dark") {
      const mctx = await browser.newContext({ viewport: { width: 1280, height: 900 }, reducedMotion: "reduce" });
      await mctx.addCookies(ck); const mp = await mctx.newPage();
      try { await mp.goto(pg.url, { waitUntil: "load", timeout: 240000 }); await mp.waitForTimeout(2000); r.motion = await mp.evaluate(() => { const a = document.getAnimations().filter((x) => x.playState === "running" && x.effect && x.effect.getComputedTiming().iterations === Infinity); return { infiniteRunning: a.length, names: [...new Set(a.map((x) => x.animationName || x.constructor.name))].slice(0, 6) }; }); } catch (e) { r.motion = { error: String(e).slice(0, 120) }; }
      await mctx.close();
    }
    results.push(r);
    const serious = r.violations.filter((v) => v.impact === "critical" || v.impact === "serious");
    console.log(`${pg.id}/${theme} ${r.status} axe:${r.violations.length} (serious+ ${serious.length}: ${serious.map((v) => `${v.id}x${v.n}`).join(",")}) focus:${r.focus?.reached ?? "-"} noRing:${r.focus?.noRingCount ?? "-"} main:${r.landmarks?.main ?? "-"} motion:${r.motion?.infiniteRunning ?? "-"}${r.error ? " ERR " + r.error : ""}`);
  }
}
await browser.close(); landing.kill();
writeFileSync(`${OUT}/qa-a11y.json`, JSON.stringify(results, null, 1));

