// r49 QA load (NOT part of the app; devhost throwaway stack only). No dependency: a small autocannon-style loop.
//   seed: devhost run -- npx tsx scripts/cyrus/qa-load.ts seed   -> .shots/load.json (keys, ids) + prints the env to set
//   run:  devhost run -- npx tsx scripts/cyrus/qa-load.ts run    (BASE=http://127.0.0.1:$PORT, SERVER_PID optional)
// Phases: A API v1 health, B API v1 with a personal key (per-key limit), C Platform API reads (per-grant call limit),
// D Platform API writes (per-grant change limit), E SQL webhook outbox backlog drain (500 events, 4 dispatchers, real
// receiver + SQL receipts). Prints p50/p95/p99 per phase, status counts and the server's RSS. Lab numbers on node-2.
import { generateKeyPairSync, randomBytes, createPrivateKey } from "node:crypto";
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { createServer } from "node:http";
import type { AddressInfo } from "node:net";
import { db } from "../../lib/db";
import { signRequest } from "../../lib/cyrus/api/v1/signing";
import { mintPlatformAssertion } from "../../lib/cyrus/host/platform";

const url = process.env.DATABASE_URL ?? "";
if (!/@127\.0\.0\.1:5433\/wt_[a-z0-9_]+/.test(url)) { console.error("refusing: not the devhost throwaway database"); process.exit(2); }
const USER = "usr_studio_all";
const FILE = ".shots/load.json";

async function seed() {
  const { privateKey, publicKey } = generateKeyPairSync("ed25519");
  const keyId = "qaload", secret = randomBytes(32).toString("base64url");
  const server = await db.server.findFirst({ where: { userId: USER, name: "guild-survival" } });
  if (!server) throw new Error("run scripts/cyrus/app-fixtures.ts first");
  const { applyConsent, createSqlGrantStore, SCOPES } = await import("../../lib/nxeon-platform/grants") as unknown as typeof import("../../lib/nxeon-platform/grants") & { SCOPES?: string[] };
  const store = createSqlGrantStore({ query: (q, ...a) => db.$queryRawUnsafe(q, ...a), exec: (q, ...a) => db.$executeRawUnsafe(q, ...a) });
  const scopes = SCOPES ?? ["servers.read", "inventory.read", "files.write.mods", "server.reload", "server.restart", "logs.read.tail", "pack.set"];
  const g = await applyConsent(store, { client: "cyrus", userId: USER, serverIds: [server.id], scopes, eligible: new Set([server.id]) });
  if (!g.ok) throw new Error(g.error);
  const { createKey } = await import("../../lib/cyrus/app/apikeys");
  const { prismaKeyStore } = await import("../../lib/cyrus/app/store");
  const k = await createKey(prismaKeyStore, USER, { name: "QA load", scopes: ["projects:read"], expiryDays: 1 });
  if (!k.ok) throw new Error(k.error);
  mkdirSync(".shots", { recursive: true });
  writeFileSync(FILE, JSON.stringify({ keyId, secret, priv: privateKey.export({ type: "pkcs8", format: "pem" }), serverId: server.id, apiKey: k.key }));
  console.log(`CYRUS_PLATFORM_KEYS=${keyId}:${secret}`);
  console.log(`CYRUS_PLATFORM_ASSERTION_PUBLIC_KEY=${String(publicKey.export({ type: "spki", format: "pem" })).replace(/\n/g, "\\n")}`);
}

type Phase = { name: string; conc: number; seconds: number; req: (i: number) => Promise<Response> };
const pct = (a: number[], p: number) => (a.length ? a[Math.min(a.length - 1, Math.floor((p / 100) * a.length))] : null);
function rss(): number | null { const pid = process.env.SERVER_PID; if (!pid) return null; try { return Math.round(Number(/VmRSS:\s+(\d+)/.exec(readFileSync(`/proc/${pid}/status`, "utf8"))![1]) / 1024); } catch { return null; } }
async function phase(p: Phase) {
  const lat: number[] = [], codes: Record<string, number> = {}; let i = 0, peakRss = rss() ?? 0;
  const end = Date.now() + p.seconds * 1000;
  const t = setInterval(() => { const r = rss(); if (r) peakRss = Math.max(peakRss, r); }, 500);
  await Promise.all(Array.from({ length: p.conc }, async () => {
    while (Date.now() < end) {
      const t0 = performance.now();
      try { const r = await p.req(i++); await r.arrayBuffer(); codes[r.status] = (codes[r.status] ?? 0) + 1; if (r.status < 400) lat.push(performance.now() - t0); }
      catch { codes.err = (codes.err ?? 0) + 1; }
    }
  }));
  clearInterval(t);
  lat.sort((a, b) => a - b);
  const r = { phase: p.name, conc: p.conc, seconds: p.seconds, requests: i, rps: Math.round(i / p.seconds), codes, okP50: pct(lat, 50)?.toFixed(1), okP95: pct(lat, 95)?.toFixed(1), okP99: pct(lat, 99)?.toFixed(1), peakRssMB: peakRss || null };
  console.log(JSON.stringify(r));
  return r;
}

async function run() {
  const base = process.env.BASE ?? `http://127.0.0.1:${process.env.PORT}`;
  const L = JSON.parse(readFileSync(FILE, "utf8"));
  const priv = createPrivateKey(L.priv);
  const plat = (method: "GET" | "POST", path: string, body = "") => {
    const h = signRequest({ keyId: L.keyId, secret: L.secret, method, pathWithQuery: path, body, nowMs: Date.now() });
    return fetch(base + path, { method, body: method === "POST" ? body : undefined, headers: { ...h, "nxeon-user-assertion": mintPlatformAssertion({ sub: USER, key: priv, nowMs: Date.now() }), ...(method === "POST" ? { "content-type": "application/json", "idempotency-key": randomBytes(12).toString("base64url") } : {}) } });
  };
  const S = `/api/platform/cyrus/v1/servers/${L.serverId}`;
  const out = [];
  out.push(await phase({ name: "A api-v1 health", conc: 20, seconds: 15, req: () => fetch(`${base}/api/cyrus/v1/health`) }));
  out.push(await phase({ name: "B api-v1 projects (personal key)", conc: 8, seconds: 20, req: () => fetch(`${base}/api/cyrus/v1/projects`, { headers: { authorization: `Bearer ${L.apiKey}` } }) }));
  out.push(await phase({ name: "C platform stat (grant)", conc: 8, seconds: 20, req: () => plat("GET", `${S}/files/stat?path=${encodeURIComponent("/opt/mc/server.properties")}`) }));
  out.push(await phase({ name: "D platform write (grant)", conc: 4, seconds: 10, req: (i) => plat("POST", `${S}/files/write`, JSON.stringify({ path: `/opt/mc/plugins/qa-load-${Date.now()}-${i}.yml`, dataB64: Buffer.from("x: 1\n").toString("base64"), ifMatch: "absent" })) }));
  out.push(await outboxDrain());
  writeFileSync(".shots/qa/qa-load.json", JSON.stringify(out, null, 1));
}

async function outboxDrain() {
  const { createSqlWebhookOutbox, outboxMetrics } = await import("../../lib/cyrus/api/v1/outbox-sql");
  const { buildFinished, dispatchWebhooks } = await import("../../lib/cyrus/api/v1/webhooks");
  const { receiveCyrusWebhook, createSqlReceipts } = await import("../../lib/cyrus-client/index");
  const SECRET = randomBytes(32).toString("hex");
  const handled = new Map<string, number>();
  const receipts = createSqlReceipts(db as never);
  // a real HTTP receiver (the Nxeon side) so the dispatcher pays real request costs
  const srv = createServer(async (req, res) => {
    const chunks: Buffer[] = []; for await (const c of req) chunks.push(c as Buffer);
    const r = await receiveCyrusWebhook(new Request("http://x/hook", { method: "POST", headers: req.headers as Record<string, string>, body: Buffer.concat(chunks) }), { secrets: [SECRET], receipts, handle: async (x) => { handled.set(x.id, (handled.get(x.id) ?? 0) + 1); } });
    res.writeHead(r.status, { "content-type": "application/json" }); res.end(await r.text());
  });
  await new Promise<void>((r) => srv.listen(0, "127.0.0.1", () => r()));
  const target = { url: `http://127.0.0.1:${(srv.address() as AddressInfo).port}/hook`, secret: SECRET };
