// r49 QA performance: LAB numbers (Playwright + Chromium on node-2, localhost, 4x CPU throttle, no network throttle)
// for the cyrus.my landing (static apps/cyrus-site) and the customer app pages on a PRODUCTION build (`next start`).
// Per page: TTFB, FCP, LCP, CLS, TBT (long tasks), an INP estimate (max event duration over a few real clicks/keys),
// transferred bytes (all / JS / CSS / images / fonts), request count. Budgets are checked and printed.
//   devhost run -- node test/e2e/cyrus-qa-perf.mjs   env: PORT, TOKENS, LANDING, OUT, RUNS (default 3, median kept)
import { createRequire } from "node:module";
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { spawn } from "node:child_process";
const require = createRequire(import.meta.url);
const { chromium } = require("playwright");

const P = process.env.PORT ?? "3000", BASE = `http://127.0.0.1:${P}`, LP = String(Number(P) + 7);
const OUT = process.env.OUT ?? ".shots/qa", RUNS = Number(process.env.RUNS ?? 3);
const tok = JSON.parse(readFileSync(process.env.TOKENS ?? ".shots/tokens.json", "utf8"));
mkdirSync(OUT, { recursive: true });
const landing = spawn("python3", ["-m", "http.server", LP, "--bind", "127.0.0.1", "--directory", process.env.LANDING ?? "apps/cyrus-site/src"], { stdio: "ignore" });
await new Promise((r) => setTimeout(r, 800));
// budgets (lab, 4x CPU): LCP <= 2.5 s, TBT <= 300 ms, CLS <= 0.1, INP-estimate <= 200 ms; weight per page kind
const BUD = { lcp: 2500, tbt: 300, cls: 0.1, inp: 200 };
const PAGES = [
  { id: "landing", url: `http://127.0.0.1:${LP}/`, auth: false, kbBudget: 2500 },
  { id: "app-home", url: `${BASE}/dashboard/cyrus/app`, auth: true, kbBudget: 900 },
  { id: "app-projects", url: `${BASE}/dashboard/cyrus/app/projects`, auth: true, kbBudget: 900 },
  { id: "app-project", url: `${BASE}/dashboard/cyrus/app/projects/mbappbounty`, auth: true, kbBudget: 900 },
  { id: "app-new", url: `${BASE}/dashboard/cyrus/app/new`, auth: true, kbBudget: 900, interact: async (p) => { const b = p.getByRole("button", { name: /Welcome titles|Lucky mob drops/ }).first(); if (await b.count()) await b.click(); } },
  { id: "app-account", url: `${BASE}/dashboard/cyrus/app/account?tab=keys`, auth: true, kbBudget: 900, interact: async (p) => { const n = p.getByLabel("Name"); if (await n.count()) await n.type("perf key", { delay: 30 }); } },
];
const browser = await chromium.launch();
const median = (a) => { const s = a.filter((x) => typeof x === "number").sort((x, y) => x - y); return s.length ? s[Math.floor(s.length / 2)] : null; };
const rows = [];
for (const pg of PAGES) {
  const runs = [];
  for (let k = 0; k < RUNS; k++) {
    const ctx = await browser.newContext({ viewport: { width: 1366, height: 860 } });
    if (pg.auth) await ctx.addCookies([{ name: tok.cookie ?? "nxeon_session", value: tok.all.token, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
    await ctx.addInitScript(() => {
      try { localStorage.setItem("nx-tour-dismissed", "1"); localStorage.setItem("cyrus-app-tour-v1", "done"); } catch {}
      window.__lab = { lcp: 0, cls: 0, tbt: 0, inp: 0 };
      new PerformanceObserver((l) => { for (const e of l.getEntries()) window.__lab.lcp = e.startTime; }).observe({ type: "largest-contentful-paint", buffered: true });
      new PerformanceObserver((l) => { for (const e of l.getEntries()) if (!e.hadRecentInput) window.__lab.cls += e.value; }).observe({ type: "layout-shift", buffered: true });
      new PerformanceObserver((l) => { for (const e of l.getEntries()) window.__lab.tbt += Math.max(0, e.duration - 50); }).observe({ type: "longtask", buffered: true });
      new PerformanceObserver((l) => { for (const e of l.getEntries()) window.__lab.inp = Math.max(window.__lab.inp, e.duration); }).observe({ type: "event", buffered: true, durationThreshold: 16 });
    });
    const page = await ctx.newPage();
    const cdp = await ctx.newCDPSession(page); await cdp.send("Emulation.setCPUThrottlingRate", { rate: 4 });
    try {
      const res = await page.goto(pg.url, { waitUntil: "load", timeout: 240000 });
      await page.waitForTimeout(3000);
      // INP estimate: real input on the page (a click on body, a Tab, the page's own interaction)
      await page.mouse.click(5, 300).catch(() => {}); await page.keyboard.press("Tab").catch(() => {});
      if (pg.interact) await pg.interact(page).catch(() => {});
      await page.waitForTimeout(800);
      const m = await page.evaluate(() => {
        const nav = performance.getEntriesByType("navigation")[0]; const fcp = performance.getEntriesByName("first-contentful-paint")[0];
        const res = performance.getEntriesByType("resource"); const kind = (r) => /\.js(\?|$)/.test(r.name) || r.initiatorType === "script" ? "js" : /\.css(\?|$)/.test(r.name) || r.initiatorType === "link" && /css/.test(r.name) ? "css" : /\.(woff2?|ttf|otf)(\?|$)/.test(r.name) ? "font" : /\.(png|jpe?g|webp|avif|gif|svg|glb|gltf)(\?|$)/.test(r.name) ? "img" : "other";
        const by = { js: 0, css: 0, font: 0, img: 0, other: 0 }; for (const r of res) by[kind(r)] += r.transferSize || r.encodedBodySize || 0;
        const doc = nav ? nav.transferSize || nav.encodedBodySize || 0 : 0;
        return { ttfb: nav ? nav.responseStart : null, fcp: fcp ? fcp.startTime : null, lcp: window.__lab.lcp || null, cls: window.__lab.cls, tbt: window.__lab.tbt, inp: window.__lab.inp || null, requests: res.length + 1, kb: Math.round((doc + Object.values(by).reduce((a, b) => a + b, 0)) / 1024), byKb: Object.fromEntries(Object.entries(by).map(([k, v]) => [k, Math.round(v / 1024)])), docKb: Math.round(doc / 1024) };
      });
      runs.push({ status: res?.status(), ...m });
      if (k === 0) await page.screenshot({ path: `${OUT}/qa-perf-${pg.id}.png` }).catch(() => {});
    } catch (e) { runs.push({ error: String(e).slice(0, 160) }); }
    await ctx.close();
  }
  const pick = (k) => median(runs.map((r) => r[k]));
  const row = { page: pg.id, status: runs[0]?.status, ttfb: pick("ttfb"), fcp: pick("fcp"), lcp: pick("lcp"), cls: pick("cls"), tbt: pick("tbt"), inp: pick("inp"), kb: pick("kb"), requests: pick("requests"), byKb: runs.find((r) => r.byKb)?.byKb ?? null, kbBudget: pg.kbBudget, errors: runs.filter((r) => r.error).map((r) => r.error) };
  row.over = [row.lcp > BUD.lcp && "LCP", row.tbt > BUD.tbt && "TBT", row.cls > BUD.cls && "CLS", row.inp > BUD.inp && "INP", row.kb > pg.kbBudget && "weight"].filter(Boolean);
  rows.push(row);
  console.log(`${pg.id} ${row.status} ttfb ${row.ttfb?.toFixed(0)} fcp ${row.fcp?.toFixed(0)} lcp ${row.lcp?.toFixed(0)} cls ${row.cls?.toFixed(3)} tbt ${row.tbt?.toFixed(0)} inp~${row.inp?.toFixed(0)} ${row.kb}KB/${row.requests}req ${JSON.stringify(row.byKb)} over:[${row.over.join(",")}]${row.errors.length ? " ERR " + row.errors[0] : ""}`);
}
await browser.close(); landing.kill();
writeFileSync(`${OUT}/qa-perf.json`, JSON.stringify({ lab: "Playwright/Chromium on node-2, localhost, 4x CPU throttle, no network throttle, median of " + RUNS, budgets: BUD, rows }, null, 1));

