// r49 QA: a tiny TLS front for `next start` on node-2, so the two-host journeys run like production (https, __Host- +
// Secure cookies, CSP upgrade-insecure-requests) without nginx. Self-signed cert for nxeon.cloud, cyrus.my and
// admin.cyrus.my (generated with openssl at start; the browser uses ignoreHTTPSErrors). Not part of the app.
//   devhost bg tls -- node test/e2e/qa-tls-proxy.mjs   env: PORT (upstream next start), TLS_PORT (default PORT+1000)
import { createServer } from "node:https";
import { request } from "node:http";
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

const UP = Number(process.env.PORT ?? 3000), PORT = Number(process.env.TLS_PORT ?? UP + 1000);
const dir = mkdtempSync(path.join(tmpdir(), "qa-tls-"));
execFileSync("openssl", ["req", "-x509", "-newkey", "rsa:2048", "-nodes", "-days", "2", "-subj", "/CN=nxeon.cloud", "-addext", "subjectAltName=DNS:nxeon.cloud,DNS:cyrus.my,DNS:admin.cyrus.my,DNS:localhost", "-keyout", path.join(dir, "k.pem"), "-out", path.join(dir, "c.pem")], { stdio: "ignore" });
createServer({ key: readFileSync(path.join(dir, "k.pem")), cert: readFileSync(path.join(dir, "c.pem")) }, (req, res) => {
  const up = request({ host: "127.0.0.1", port: UP, method: req.method, path: req.url, headers: { ...req.headers, "x-forwarded-proto": "https", "x-forwarded-host": req.headers.host ?? "" } }, (r) => { res.writeHead(r.statusCode ?? 502, r.headers); r.pipe(res); });
  up.on("error", (e) => { res.writeHead(502); res.end(String(e)); });
  req.pipe(up);
}).listen(PORT, "127.0.0.1", () => console.log(`tls proxy https://127.0.0.1:${PORT} -> http://127.0.0.1:${UP}`));

