content.content:
.cyrus-root .animate-rise { animation: cy5-rise-in 0.55s var(--ease-out-expo) both; }
.cyrus-root .animate-fade { animation: cy5-fade-in 0.4s ease both; }
.cyrus-root .animate-slide-right { animation: cy5-slide-in-right 0.5s var(--ease-out-expo) both; }
.cyrus-root .animate-pop { animation: cy5-pop-in 0.28s var(--ease-out-expo) both; }

@media (prefers-reduced-motion: reduce) {
  .cyrus-root .core-sparks .spark, .cyrus-root .brain * {
    animation: none !important;
  }
  .cyrus-root .brain-signal {
    display: none;
  }
}

/* ───────────────────────── Cosmos backdrop ───────────────────────── */

.cyrus-root .cosmos {
  position: fixed;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  background:
    radial-gradient(90% 70% at 50% 46%, #0d1030 0%, #080a1f 38%, #04050f 72%, #020309 100%),
    var(--bg);
}
html[data-theme="light"] .cyrus-root .cosmos {
@keyframes cy-pop { from { opacity: 0; transform: scale(.9); } }
@keyframes cy-toast { from { opacity: 0; transform: translateY(10px); } }
@keyframes cy-line { from { opacity: 0; transform: translateX(-3px); } }
@keyframes cy-glow { 0% { background: var(--cy-accent-soft); box-shadow: inset 2px 0 0 var(--cy-accent-ink); } 100% { background: transparent; box-shadow: inset 2px 0 0 transparent; } }
@media (prefers-reduced-motion: reduce) {
  :is(.cy-tokens) *, :is(.cy-tokens) *::before, :is(.cy-tokens) *::after { animation-duration: .001ms !important; animation-iteration-count: 1 !important; transition-duration: .001ms !important; }
}
