import { createRequire } from "node:module"; import { readFileSync } from "node:fs";
const require = createRequire(import.meta.url); const { chromium } = require("playwright");
const tok = JSON.parse(readFileSync(".shots/tokens.json", "utf8")); const BASE = `http://127.0.0.1:${process.env.PORT}`;
const b = await chromium.launch(); const ctx = await b.newContext();
await ctx.addCookies([{ name: tok.cookie ?? "nxeon_session", value: tok.all.token, url: BASE }]);
await ctx.route(/^https?:\/\/(?!(127\.0\.0\.1)[:/])/, (r) => r.abort());
const p = await ctx.newPage(); const sizes = [];
p.on("response", async (r) => { if (/\.js/.test(r.url())) { const b = await r.body().catch(() => null); sizes.push([b ? b.length : 0, r.headers()["content-encoding"] ?? "-", r.url().replace(BASE, "")]); } });
await p.goto(`${BASE}/dashboard/cyrus/app`, { waitUntil: "load" }); await p.waitForTimeout(3000);
sizes.sort((a, c) => c[0] - a[0]); console.log("total", Math.round(sizes.reduce((a, x) => a + x[0], 0) / 1024), "KB raw in", sizes.length, "files");
for (const s of sizes.slice(0, 10)) console.log(Math.round(s[0] / 1024) + "KB", s[1], s[2]);
await b.close();
EOF
