import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { modBuilderMetadata, requireModBuilderUser } from "@/lib/modbuilder/access";
import { modelStudioViewer } from "@/lib/cyrus/modelstudio/deps";
import { MeshStudio } from "@/components/cyrus/modelstudio/retex/MeshStudio";
import { studioContext } from "../../../studio-shared";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return modBuilderMetadata("Model Studio · Mesh · Cyrus");
}

/**
 * Model Studio layer 3: mesh retexture + light edit (glTF from meshgen or an import). Same gates as layer 1: the
 * Cyrus access rule -> the studios gate -> Model Studio's own visibility (cyrus_model_studio_enabled OR a preview
 * account; else 404). Every plan may VIEW; edits are refused by the API below "All models" (fail closed), and the
 * page shows the view-only state from the same decision.
 */
export default async function MeshStudioPage({ params, searchParams }: { params: Promise<{ id: string }>; searchParams: Promise<{ mesh?: string | string[] }> }) {
  await requireModBuilderUser();
  const { id } = await params;
  const { mod } = await studioContext(id, "mesh");
  if (!(await modelStudioViewer())) notFound();
  const m = (await searchParams).mesh;
  return <MeshStudio mod={mod} initialKey={typeof m === "string" && /^[a-z][a-z0-9_]{0,47}$/.test(m) ? m : null} />;
}
